import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.BsLG2nmw.js";const r="/my-blog/assets/1780829036304-59ebax4z0gw.Nyc9A7Q0.png",a="/my-blog/assets/1780829036646-3zclq16a0me.ChGjrJix.png",i="/my-blog/assets/1780829036995-3l7z41n0s9i.CLKdHf7X.png",l="/my-blog/assets/1780829037320-d5drfb814av.Px5BbITy.png",d="/my-blog/assets/1780829037662-l2j8j9jlz8.ts_COwO9.png",w=JSON.parse('{"title":"突破校园网限制：Windows+Ubuntu虚拟机+Linux开发板的高效联调网络拓扑","description":"","frontmatter":{"title":"突破校园网限制：Windows+Ubuntu虚拟机+Linux开发板的高效联调网络拓扑","category":"随笔","subCategory":"NetWork","subSubCategory":""},"headers":[],"relativePath":"posts/essay/network/net-ubuntu.md","filePath":"posts/essay/network/net-ubuntu.md"}'),c={name:"posts/essay/network/net-ubuntu.md"};function p(u,o,g,h,b,_){return t(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="突破校园网限制-windows-ubuntu虚拟机-linux开发板的高效联调网络拓扑" tabindex="-1">突破校园网限制：Windows+Ubuntu虚拟机+Linux开发板的高效联调网络拓扑 <a class="header-anchor" href="#突破校园网限制-windows-ubuntu虚拟机-linux开发板的高效联调网络拓扑" aria-label="Permalink to &quot;突破校园网限制：Windows+Ubuntu虚拟机+Linux开发板的高效联调网络拓扑&quot;">​</a></h1><p>在进行嵌入式 Linux 系统开发（如 <a href="http://i.mx/" target="_blank" rel="noreferrer">i.MX</a>6ULL 车载中控终端或 Allwinner T113 智能桌面屏幕项目）时，我们通常需要同时使用 Windows 主机（运行 MobaXterm 的 TFTP 服务）、Ubuntu 虚拟机（提供 NFS 根文件系统和 SSH 编译环境）以及物理开发板。</p><p>然而，在校园网环境下，由于 <strong>AP 隔离</strong>以及<strong>严格的设备数量限制</strong>（通常仅限一台 PC 和一台移动设备），常规的路由器直连或虚拟机桥接方案往往难以奏效。本文记录了一种基于 Windows 底层网桥与网络共享（ICS）的终极解决方案。</p><h2 id="核心拓扑思路" tabindex="-1">核心拓扑思路 <a class="header-anchor" href="#核心拓扑思路" aria-label="Permalink to &quot;核心拓扑思路&quot;">​</a></h2><p>放弃容易与 Windows 产生冲突的 VMware 自带桥接（VMnet0），利用 Windows 自身的网桥（Network Bridge）将“开发板的 USB 网卡”与“虚拟机的仅主机网卡（VMnet1）”绑定成一个纯粹的内部局域网。随后，将连接校园网的 Wi-Fi 共享给该网桥。</p><p><strong>网络角色划分：</strong></p><ul><li><strong>对外</strong>：校园网仅能看到 Windows 主机的 Wi-Fi 网卡，完美绕过设备限制。</li><li><strong>对内</strong>：网桥充当虚拟交换机与网关（IP 固定为 <code>192.168.137.1</code>），为虚拟机和开发板分配同网段 IP，实现全互通且均可访问外网。</li></ul><h2 id="详细配置步骤" tabindex="-1">详细配置步骤 <a class="header-anchor" href="#详细配置步骤" aria-label="Permalink to &quot;详细配置步骤&quot;">​</a></h2><h3 id="_1-配置虚拟机网卡为-仅主机模式" tabindex="-1">1. 配置虚拟机网卡为“仅主机模式” <a class="header-anchor" href="#_1-配置虚拟机网卡为-仅主机模式" aria-label="Permalink to &quot;1. 配置虚拟机网卡为“仅主机模式”&quot;">​</a></h3><ol><li><p>关闭 Ubuntu 虚拟机。</p></li><li><p>打开 VMware 虚拟机设置，将“网络适配器”的网络连接更改为 <strong>“自定义 (特定虚拟网络)”</strong>。</p></li><li><p>在下拉菜单中选择 <strong><code>VMnet1 (仅主机模式)</code></strong>，保存退出。</p><p><img src="'+r+'" alt="vmware_GUsLk53Ijt.png"></p></li></ol><h3 id="_2-建立-windows-物理网桥" tabindex="-1">2. 建立 Windows 物理网桥 <a class="header-anchor" href="#_2-建立-windows-物理网桥" aria-label="Permalink to &quot;2. 建立 Windows 物理网桥&quot;">​</a></h3><ol><li>在 Windows 中按 <code>Win + R</code> 输入 <code>ncpa.cpl</code> 打开网络连接。</li><li>按住 <code>Ctrl</code> 键，同时选中连接开发板的 <strong>USB 网卡（以太网 3）</strong> 和虚拟机的虚拟网卡 <strong>VMware Network Adapter VMnet1</strong>。</li><li>右键点击其中任意一个，选择 <strong>“桥接 (Bridge Connections)”</strong>，等待系统生成名为 <strong>“网桥”</strong> 的新图标。</li></ol><p><img src="'+a+'" alt="explorer_bB0hEO8XKm.png"></p><h3 id="_3-配置-internet-连接共享-ics" tabindex="-1">3. 配置 Internet 连接共享 (ICS) <a class="header-anchor" href="#_3-配置-internet-连接共享-ics" aria-label="Permalink to &quot;3. 配置 Internet 连接共享 (ICS)&quot;">​</a></h3><ol><li>找到当前连接校园网并能正常上网的 <strong>WLAN (Wi-Fi)</strong> 网卡。</li><li>右键点击 -&gt; <strong>属性</strong> -&gt; 共享 选项卡。</li><li>勾选“允许其他网络用户通过此计算机的 Internet 连接来连接”。</li><li>在家庭网络连接的下拉菜单中，务必选择刚刚生成的 <strong>“网桥”</strong>，点击确定。 <em>(此时，Windows 会强制将网桥的 IP 设置为</em> <em><code>192.168.137.1</code>__)</em></li></ol><p><img src="'+i+'" alt="dllhost_tpDC6nZX5X.png"></p><h3 id="_4-解决-usb-网卡底层丢包问题-关键避坑" tabindex="-1">4. 解决 USB 网卡底层丢包问题 (关键避坑) <a class="header-anchor" href="#_4-解决-usb-网卡底层丢包问题-关键避坑" aria-label="Permalink to &quot;4. 解决 USB 网卡底层丢包问题 (关键避坑)&quot;">​</a></h3><p>多数 USB 转网口芯片在底层阉割了“混杂模式 (Promiscuous Mode)”，加入网桥后会出现“只发不收”的数据包丢失现象（如 Ubuntu 报 <code>Destination Host Unreachable</code>）。必须通过命令行强制开启兼容模式：</p><ol><li><p>以<strong>管理员身份</strong>运行命令提示符 (CMD)。</p></li><li><p>输入 <code>netsh bridge show adapter</code> 查询网桥内的网卡编号（记录 USB 网卡对应的 <code>IfIndex</code> 数字）。</p></li><li><p>输入以下命令强制开启兼容模式（将 <code>N</code> 替换为实际编号）：DOS</p><p><code>netsh bridge set adapter N forcecompatmode=enable</code></p></li><li><p>重新插拔开发板网线，触发硬件重新握手。</p></li></ol><p><img src="'+l+'" alt="powershell_fyRjfbxBn1.png"></p><h3 id="_5-联调服务映射清单" tabindex="-1">5. 联调服务映射清单 <a class="header-anchor" href="#_5-联调服务映射清单" aria-label="Permalink to &quot;5. 联调服务映射清单&quot;">​</a></h3><p>完成上述配置后，整个局域网即可顺畅运作：</p><ul><li><strong>TFTP 服务 (下载内核/设备树)</strong>：在 Windows 运行 MobaXterm，TFTP 服务器 IP 指向网关 <code>192.168.137.1</code>。开发板 U-Boot 可直接拉取。</li><li><strong>SSH 远程开发</strong>：在 Ubuntu 中通过 <code>ifconfig</code> 查看分配到的 IP（如 <code>192.168.137.248</code>），Windows 使用 VSCode 即可直接 SSH 连接。</li><li><strong>NFS 挂载根文件系统</strong>：开发板启动 Linux 内核后，设置 <code>bootargs</code> 中的 <code>nfsroot</code> 参数，指向虚拟机的 IP 及共享路径（例如 <code>nfsroot=192.168.137.248:/home/user/nfs</code>），即可成功挂载。</li></ul><h1 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h1><ol><li>缺点就是开发板子在通过 tftp 拉取 zImage 镜像文件的时候，速度会比较慢，大概需要花费 1-2 分钟，速度比较慢，只有 100k 左右的网速</li></ol><p><img src="'+d+'" alt="MobaXterm_6Xg9pyp0uN.png"></p>',26)])])}const f=e(c,[["render",p]]);export{w as __pageData,f as default};
